import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, TrendingUp, TrendingDown, Activity, Target } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'bg-red-50 text-red-600 border-red-100',
      accent: 'bg-red-50/30 border-red-200 text-red-900',
      icon: <TrendingUp className="w-3.5 h-3.5" />
    };
    case '看跌': return {
      color: 'bg-green-50 text-green-600 border-green-100',
      accent: 'bg-green-50/30 border-green-200 text-green-900',
      icon: <TrendingDown className="w-3.5 h-3.5" />
    };
    case '震荡': return {
      color: 'bg-blue-50 text-blue-600 border-blue-100',
      accent: 'bg-blue-50/30 border-blue-200 text-blue-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
    default: return {
      color: 'bg-gray-50 text-gray-500 border-gray-100',
      accent: 'bg-gray-50/30 border-gray-200 text-gray-900',
      icon: <Activity className="w-3.5 h-3.5" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const completionStatus = insight.completionStatus;
  const { color, icon, accent } = getAssetStatusStyle(insight.status);

  const getCardStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-white border-emerald-100 shadow-[0_4px_20px_-4px_rgba(16,185,129,0.05)] hover:shadow-[0_20px_40px_-10px_rgba(16,185,129,0.1)]';
      case '已失效': return 'bg-[#fafafa] border-slate-200 opacity-80 grayscale';
      default: return 'bg-white border-gray-200 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_20px_40px_-10px_rgba(0,0,0,0.08)] hover:-translate-y-1';
    }
  };

  const getTagStyle = () => {
    switch (completionStatus) {
      case '已完成': return 'bg-emerald-500 text-white shadow-xl shadow-emerald-100'; 
      case '已失效': return 'bg-slate-500 text-white shadow-xl shadow-slate-100'; 
      default: return 'bg-red-500 text-white shadow-xl shadow-red-100';
    }
  };

  const getStatusIndicator = () => {
    switch (completionStatus) {
      case '已完成': return <div className="w-2 h-2 rounded-full bg-white shadow-sm" />; 
      case '已失效': return <div className="w-2 h-2 rounded-full bg-white/60 shadow-sm" />;     
      default: return <div className="w-2 h-2 rounded-full bg-white animate-pulse shadow-sm shadow-white" />;
    }
  };

  return (
    <div className={`group relative mt-4 border rounded-[2.5rem] p-7 pt-9 transition-all duration-500 flex flex-col min-h-[420px] ${getCardStyle()}`}>

      {/* 状态标签 - 置顶操作入口 */}
      <div className="absolute -top-3.5 left-8 flex gap-2 z-30">
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`flex items-center gap-2.5 px-5 py-2.5 rounded-full text-[11px] font-black uppercase tracking-wider shadow-xl transition-all active:scale-95 hover:brightness-110 cursor-pointer ${getTagStyle()}`}
        >
          {getStatusIndicator()}
          <span>{completionStatus}</span>
        </button>
      </div>

      <div className="relative z-10 flex justify-between items-center mb-6">
        <div>
          <h3 className="text-3xl font-black text-gray-900 tracking-tighter mb-1.5">{insight.symbol}</h3>
          <div className="flex items-center text-[11px] text-gray-400 gap-1.5 font-bold">
            <Calendar className="w-3.5 h-3.5 opacity-60" />
            {date}
          </div>
        </div>
        <div className={`px-4 py-2 rounded-2xl text-[12px] font-black border flex items-center gap-2 shadow-sm ${color}`}>
          {insight.status}
          {icon}
        </div>
      </div>

      <div className="relative z-10 space-y-5 flex-grow">
        <div className={`p-5 rounded-3xl border transition-colors ${completionStatus === '进行中' ? 'bg-gray-50/50 border-gray-100' : 'bg-white/40 border-transparent'}`}>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400 mb-2.5">核心观察</p>
          <p className="text-[14px] leading-relaxed font-medium text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center justify-between p-4 px-5 rounded-2xl border border-dashed bg-gray-50 border-gray-200">
            <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">入场参考</p>
            <div className="flex items-center gap-2">
              <Target className="w-3.5 h-3.5 text-red-400" />
              <p className="text-lg font-black tracking-tighter text-gray-900">{insight.entryLevel}</p>
            </div>
          </div>
        )}

        <div className={`p-6 rounded-3xl border-l-[8px] transition-all ${completionStatus === '进行中' ? accent : completionStatus === '已完成' ? 'bg-emerald-50/30 border-emerald-200 text-emerald-900' : 'bg-gray-100 border-gray-300 text-gray-500'}`}>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60 mb-2.5">执行策略</p>
          <p className={`text-[15px] font-bold leading-relaxed ${completionStatus === '进行中' ? 'text-gray-900' : completionStatus === '已完成' ? 'text-emerald-900' : 'text-gray-400'}`}>
            {insight.strategy}
          </p>
        </div>
      </div>

      {/* 控制按钮栏 */}
      <div className="relative z-10 mt-6 pt-6 border-t border-gray-100/60 flex justify-end items-center gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
        <button 
          onClick={() => onEdit(insight)}
          className="px-4 py-2 text-gray-400 hover:text-gray-900 hover:bg-gray-50 rounded-xl transition-all flex items-center gap-2 text-[12px] font-black"
        >
          <Edit2 className="w-4 h-4" />
          编辑
        </button>
        <button 
          onClick={() => onDelete(insight.id)}
          className="px-4 py-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all flex items-center gap-2 text-[12px] font-black"
        >
          <Trash2 className="w-4 h-4" />
          删除
        </button>
      </div>
    </div>
  );
};

export default MarketCard;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, Clock, Calendar, Hash, ListFilter, CalendarDays, Archive } from 'lucide-react';
import MarketDashboard from './components/MarketDashboard';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v2');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');

  useEffect(() => {
    localStorage.setItem('trading_journal_v2', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        return { ...i, completionStatus: statuses[(currentIndex + 1) % statuses.length] };
      }
      return i;
    }));
  };

  const handleGenerateAI = async () => {
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-red-100 selection:text-red-900 bg-[#fbfbfb]">
      {/* 主导航栏 */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-3xl border-b border-gray-100 px-8 py-5 h-[89px]">
        <div className="max-w-[1600px] mx-auto grid grid-cols-[240px_1fr_240px] items-center h-full">
          <div className="flex items-center gap-4">
            {/* 保留圆形的logo */}
            <div className="bg-gray-900 p-3 rounded-full shadow-xl shadow-gray-200">
              <LayoutGrid className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-gray-900 tracking-tight leading-none mb-1">市场周刊</h1>
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Market Weekly</p>
            </div>
          </div>

          <div className="flex justify-center">
            <nav className="flex items-center bg-gray-100/60 p-1.5 rounded-2xl border border-gray-100 gap-1.5 shadow-inner">
              {CATEGORIES.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`px-7 py-2.5 rounded-xl text-[14px] font-black transition-all whitespace-nowrap active:scale-95 relative ${
                    activeCategory === cat ? 'bg-white text-gray-900 shadow-xl shadow-gray-200/40 border border-gray-50' : 'text-gray-400 hover:text-gray-900 hover:bg-white/40'
                  }`}
                >
                  {cat}
                  {activeCategory === cat && <span className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-red-500 rounded-full"></span>}
                </button>
              ))}
            </nav>
          </div>

          <div className="flex items-center gap-3 justify-end">
            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-red-500 text-white px-7 py-3.5 rounded-2xl hover:bg-red-600 transition-all flex items-center gap-2.5 shadow-2xl shadow-red-200 font-black text-sm active:scale-95 group"
            >
              <Plus className="w-4 h-4 transition-transform group-hover:rotate-90" />
              <span>新观点</span>
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-14 w-full flex flex-col lg:flex-row gap-16">
        <aside className="lg:w-64 space-y-12 flex-shrink-0">
          <div className="sticky top-[120px]">
            <div className="flex items-center gap-2.5 mb-8 px-1">
              <Clock className="w-4 h-4 text-gray-400" />
              <h3 className="text-[12px] font-black text-gray-400 uppercase tracking-[0.2em]">时间归档</h3>
            </div>
            <div className="space-y-3">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-5 py-4 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                  selectedMonth === null ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                }`}
              >
                <span className="flex items-center gap-3">
                  <Hash className={`w-4 h-4 ${selectedMonth === null ? 'text-red-500' : 'text-gray-300'}`} />
                  所有时间
                </span>
                <span className={`text-[11px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === null ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                  {insights.length}
                </span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-5 py-4 rounded-2xl text-[13px] font-black transition-all flex items-center justify-between group border-2 ${
                    selectedMonth === month ? 'bg-white border-gray-900 shadow-xl shadow-gray-100 text-gray-900' : 'bg-transparent border-transparent text-gray-400 hover:text-gray-900 hover:bg-white hover:border-gray-100'
                  }`}
                >
                  <span className="flex items-center gap-3">
                    <Calendar className={`w-4 h-4 ${selectedMonth === month ? 'text-red-500' : 'text-gray-300'}`} />
                    {month}
                  </span>
                  <span className={`text-[11px] px-2 py-0.5 rounded-lg font-black ${selectedMonth === month ? 'bg-red-50 text-red-500' : 'bg-gray-100 text-gray-400'}`}>
                    {count}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          <MarketDashboard 
            insights={insights} 
            onGenerateAI={handleGenerateAI} 
            isGeneratingAI={isGeneratingAI} 
            aiSummary={aiSummary} 
          />

          <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-8 mb-16">
            <div className="space-y-3">
              <p className="text-[12px] font-black text-red-500 uppercase tracking-[0.4em]">Current Insights</p>
              <h2 className="text-4xl font-black text-gray-900 tracking-tight italic">
                保持专注，记录市场的每一次心跳。
              </h2>
            </div>

            <div className="flex bg-gray-100 p-1.5 rounded-2xl items-center border border-gray-100">
              <button onClick={() => setSortMode('category')} className={`px-6 py-3 rounded-xl text-[11px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-lg border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-2 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-6 py-3 rounded-xl text-[11px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-lg border border-gray-50' : 'text-gray-400 hover:text-gray-600'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-2 inline" /> 时间
              </button>
            </div>
          </div>

          {activeItems.length > 0 ? (
            <div className="space-y-8">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel} className="relative pt-4">
                  {/* 分类标题：非粘性，随页面自然滚动 */}
                  <div className="relative py-12 transition-all duration-300">
                    <div className="relative flex items-center w-full">
                      {/* 背景装饰线 */}
                      <div className="absolute inset-0 flex items-center pointer-events-none" aria-hidden="true">
                        <div className="w-full h-[1px] bg-gray-100"></div>
                      </div>
                      {/* 黑色胶囊标签 - 仿 YouMind 样式 */}
                      <div className="relative z-10 bg-[#12141c] text-white px-7 py-3 rounded-full shadow-[0_15px_35px_-12px_rgba(0,0,0,0.4)] flex items-center gap-3">
                         <div className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(239,68,68,0.8)]"></div>
                         <span className="text-[14px] font-black tracking-widest uppercase">{groupLabel}</span>
                         <span className="text-[10px] text-gray-400 font-bold bg-white/5 px-2.5 py-1 rounded-lg ml-1 border border-white/10">{groupItems.length}</span>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-x-12 gap-y-12 pb-16">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-48 bg-white rounded-[4rem] border border-dashed border-gray-200 shadow-sm">
              <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
                <Plus className="w-8 h-8 text-gray-300" />
              </div>
              <h3 className="text-2xl font-black text-gray-900 mb-2">暂无活跃市场观点</h3>
              <p className="text-sm text-gray-400 max-w-xs mx-auto">现在就去创建你的第一条市场记录，开启专业交易日志之旅。</p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-40 space-y-12">
               <div className="flex items-center gap-6 border-t border-gray-100 pt-24 mb-12">
                  <Archive className="w-7 h-7 text-gray-300" />
                  <h3 className="text-2xl font-black text-gray-300 tracking-tight">已归档的历史回顾</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-x-12 gap-y-16">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto border-t border-gray-100 py-20 bg-white text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.6em]">Trading Journal Pro · Digital Assets Intelligence · 2025</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MarketInsight, AssetStatus, CompletionStatus } from '../types';
import { X, Calendar as CalendarIcon } from 'lucide-react';
import { CATEGORIES } from '../constants';

interface InsightFormProps {
  initialData?: MarketInsight;
  onSave: (data: Partial<MarketInsight>) => void;
  onCancel: () => void;
}

const InsightForm: React.FC<InsightFormProps> = ({ initialData, onSave, onCancel }) => {
  const [formData, setFormData] = useState<Partial<MarketInsight>>(
    initialData || {
      symbol: '',
      category: '美股',
      status: '震荡',
      focusPoints: '',
      strategy: '',
      entryLevel: '',
      updatedAt: Date.now(),
      completionStatus: '进行中',
    }
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  const formatDateForInput = (timestamp?: number) => {
    if (!timestamp) return new Date().toISOString().split('T')[0];
    return new Date(timestamp).toISOString().split('T')[0];
  };

  const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md">
      <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-xl overflow-hidden animate-in fade-in zoom-in duration-300 border border-gray-100">
        <div className="p-6 px-8 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
          <h2 className="text-xl font-black text-gray-900 tracking-tight">
            {initialData ? '更新市场观点' : '记录新观点'}
          </h2>
          <button onClick={onCancel} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X className="w-5 h-5 text-gray-500" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-5 max-h-[85vh] overflow-y-auto">
          {/* 完成状态选择 */}
          <div className="bg-gray-50 p-5 rounded-2xl space-y-3 border border-gray-100">
            <div>
              <p className="text-sm font-black text-gray-900">观点进展状态</p>
              <p className="text-[10px] text-gray-400 font-bold uppercase tracking-wider">选择状态将改变卡片配色方案</p>
            </div>
            <div className="flex gap-2">
              {statuses.map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => setFormData({ ...formData, completionStatus: s })}
                  className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl text-xs font-black transition-all ${
                    formData.completionStatus === s
                      ? s === '已完成' ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-100' 
                        : s === '已失效' ? 'bg-slate-500 text-white shadow-lg shadow-slate-100'
                        : 'bg-red-500 text-white shadow-lg shadow-red-100'
                      : 'bg-white text-gray-400 border border-gray-200 hover:border-gray-300'
                  }`}
                >
                  <div className={`w-1.5 h-1.5 rounded-full ${formData.completionStatus === s ? 'bg-white' : 'bg-gray-300'}`} />
                  {s}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1 flex items-center gap-1">
                <CalendarIcon className="w-3 h-3" /> 记录日期
              </label>
              <input
                type="date"
                className="w-full p-3.5 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all text-sm font-bold"
                value={formatDateForInput(formData.updatedAt)}
                onChange={(e) => {
                  const selectedDate = new Date(e.target.value);
                  setFormData({ ...formData, updatedAt: selectedDate.getTime() });
                }}
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">资产代码</label>
              <input
                required
                className="w-full p-3.5 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all text-sm font-black"
                value={formData.symbol}
                onChange={(e) => setFormData({ ...formData, symbol: e.target.value.toUpperCase() })}
                placeholder="例如: BTC"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">所属分类</label>
              <select
                className="w-full p-3.5 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all appearance-none text-sm font-bold"
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              >
                {CATEGORIES.filter(c => c !== '全部').map(c => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">行情状态</label>
              <select
                className="w-full p-3.5 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all appearance-none text-sm font-bold"
                value={formData.status}
                onChange={(e) => setFormData({ ...formData, status: e.target.value as AssetStatus })}
              >
                <option value="看涨">看涨 (Bullish)</option>
                <option value="看跌">看跌 (Bearish)</option>
                <option value="震荡">震荡 (Oscillating)</option>
              </select>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">核心观察</label>
            <textarea
              required
              rows={3}
              className="w-full p-4 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all text-sm leading-relaxed font-bold"
              value={formData.focusPoints}
              onChange={(e) => setFormData({ ...formData, focusPoints: e.target.value })}
              placeholder="记录关键的价格行为..."
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">拟定策略</label>
              <textarea
                required
                rows={2}
                className="w-full p-4 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all text-sm leading-relaxed font-bold"
                value={formData.strategy}
                onChange={(e) => setFormData({ ...formData, strategy: e.target.value })}
                placeholder="拟定交易计划..."
              />
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">入场点位</label>
              <input
                className="w-full p-3.5 bg-gray-50 border border-transparent focus:bg-white focus:border-gray-900 rounded-2xl outline-none transition-all text-sm font-black"
                value={formData.entryLevel}
                onChange={(e) => setFormData({ ...formData, entryLevel: e.target.value })}
                placeholder="例如: 92,500.00"
              />
            </div>
          </div>

          <div className="pt-6 flex gap-4">
            <button
              type="button"
              onClick={onCancel}
              className="flex-1 py-4 px-6 rounded-2xl border border-gray-100 text-gray-500 font-black text-sm hover:bg-gray-50 transition-colors"
            >
              取消
            </button>
            <button
              type="submit"
              className="flex-1 py-4 px-6 rounded-2xl bg-gray-900 text-white font-black text-sm hover:bg-black transition-colors shadow-xl shadow-gray-200"
            >
              {initialData ? '确认更新' : '立即保存'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default InsightForm;

